package dev.eugheist.ttmodern;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.AABB;
final class AnimationTabletAudit{
    static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT PORT AUDIT FAILED: tablet "+label);}
    static void run(ServerLevel level){var pos=new BlockPos(8,300,40);var at=pos.north();try{
        level.setBlockAndUpdate(pos,ThaumicTinkererModern.ANIMATION_TABLET.get().defaultBlockState());var tile=(AnimationTabletEntity)level.getBlockEntity(pos);check(tile.target().equals(at),"front target");tile.inventory.setStackInSlot(0,new ItemStack(Items.DIAMOND_PICKAXE));level.setBlockAndUpdate(at,Blocks.STONE.defaultBlockState());
        for(int i=0;i<15;i++)AnimationTabletEntity.tick(level,pos,tile.getBlockState(),tile);check(level.getBlockState(at).is(Blocks.STONE),"windup does not instantly mine");for(int i=0;i<250&&!level.isEmptyBlock(at);i++)AnimationTabletEntity.tick(level,pos,tile.getBlockState(),tile);
        check(level.isEmptyBlock(at)&&tile.inventory.getStackInSlot(0).getDamageValue()==1,"real progressive harvest consumes tool durability");check(level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(at).inflate(2)).stream().anyMatch(e->e.getItem().is(Items.COBBLESTONE)),"correct survival mining drop");
        for(var drop:level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(at).inflate(2)))drop.discard();
        tile.stopBreaking();tile.swingProgress=tile.swingMod=0;level.setBlockAndUpdate(at,Blocks.STONE.defaultBlockState());
        var denied=new java.util.concurrent.atomic.AtomicInteger();java.util.function.Consumer<net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.LeftClickBlock> deny=event->{if(event.getPos().equals(at)){denied.incrementAndGet();event.setCanceled(true);}};net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener(deny);try{tile.hit();check(denied.get()==1&&!tile.breaking&&level.getBlockState(at).is(Blocks.STONE),"cancelled left click never starts breaking");}finally{net.neoforged.neoforge.common.NeoForge.EVENT_BUS.unregister(deny);}
        var breakEvents=new java.util.concurrent.atomic.AtomicInteger();java.util.function.Consumer<net.neoforged.neoforge.event.level.BlockEvent.BreakEvent> cancelBreak=event->{if(event.getPos().equals(at)){breakEvents.incrementAndGet();event.setCanceled(true);}};net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener(cancelBreak);try{int beforeDamage=tile.inventory.getStackInSlot(0).getDamageValue();tile.hit();for(int i=0;i<250&&tile.breaking;i++)tile.continueBreaking();check(breakEvents.get()==1&&level.getBlockState(at).is(Blocks.STONE)&&tile.inventory.getStackInSlot(0).getDamageValue()==beforeDamage,"cancelled final harvest preserves block and durability");}finally{net.neoforged.neoforge.common.NeoForge.EVENT_BUS.unregister(cancelBreak);tile.stopBreaking();}
        level.removeBlock(at,false);tile.inventory.setStackInSlot(0,new ItemStack(Items.DIAMOND_SWORD));var cow=net.minecraft.world.entity.EntityType.COW.create(level);cow.moveTo(at.getX()+.5,at.getY(),at.getZ()+.5,0,0);cow.setNoAi(true);level.addFreshEntity(cow);float health=cow.getHealth();tile.hit();check(cow.getHealth()<health&&tile.inventory.getStackInSlot(0).getDamageValue()==1,"actual sword attack and durability");
        tile.leftClick=false;tile.inventory.setStackInSlot(0,new ItemStack(Items.WHEAT,2));var interactions=new java.util.concurrent.atomic.AtomicInteger();java.util.function.Consumer<net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.EntityInteract> cancelEntity=event->{if(event.getTarget()==cow){interactions.incrementAndGet();event.setCanceled(true);}};net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener(cancelEntity);try{tile.hit();check(interactions.get()==1&&!cow.isInLove()&&tile.inventory.getStackInSlot(0).getCount()==2,"cancelled entity interaction cannot feed or consume wheat");}finally{net.neoforged.neoforge.common.NeoForge.EVENT_BUS.unregister(cancelEntity);}tile.leftClick=true;var fragile=new ItemStack(Items.DIAMOND_SWORD);fragile.setDamageValue(fragile.getMaxDamage()-1);tile.inventory.setStackInSlot(0,fragile);cow.setHealth(cow.getMaxHealth());cow.invulnerableTime=0;tile.hit();check(tile.inventory.getStackInSlot(0).isEmpty()&&tile.player.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE)==1,"broken weapon cannot leak attack modifiers");cow.discard();
        tile.leftClick=false;tile.inventory.setStackInSlot(0,new ItemStack(Items.DIAMOND_HOE));level.setBlockAndUpdate(at,Blocks.DIRT.defaultBlockState());tile.hit();check(level.getBlockState(at).is(Blocks.FARMLAND)&&tile.inventory.getStackInSlot(0).getDamageValue()==1,"right click uses hoe on real block");
        level.setBlockAndUpdate(at,Blocks.STONE.defaultBlockState());tile.inventory.setStackInSlot(0,new ItemStack(Items.DIAMOND_PICKAXE));tile.leftClick=true;tile.redstone=true;tile.swingProgress=tile.swingMod=0;for(int i=0;i<40;i++)AnimationTabletEntity.tick(level,pos,tile.getBlockState(),tile);check(tile.swingProgress==0&&!tile.breaking,"redstone control prevents automatic swings");check(tile.trigger()&&!tile.trigger(),"trigger refuses busy tablet");
        var copy=new AnimationTabletEntity(pos,tile.getBlockState());copy.loadWithComponents(tile.saveWithoutMetadata(level.registryAccess()),level.registryAccess());check(copy.leftClick&&copy.redstone&&copy.swingProgress==1&&copy.swingMod==3&&copy.inventory.getStackInSlot(0).is(Items.DIAMOND_PICKAXE),"inventory/modes/animation roundtrip");
        var player=tile.player();player.getInventory().setItem(1,new ItemStack(Items.BOOK,3));tile.finishPlayer(player);check(player.getInventory().isEmpty()&&level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(pos).inflate(2)).stream().anyMatch(e->e.getItem().is(Items.BOOK)&&e.getItem().getCount()==3),"extra fake player items dropped without loss");
        var menu=new AnimationTabletMenu(1,player.getInventory(),tile);player.moveTo(pos.getX()+.5,pos.getY()+1,pos.getZ()+.5);check(menu.clickMenuButton(player,2)&&!tile.leftClick&&!menu.clickMenuButton(player,3),"server validates mode buttons");player.moveTo(1000,300,1000);check(!menu.clickMenuButton(player,1),"distant menu cannot control tablet");
        var recipe=dev.eugheist.tc4modern.ArcaneRecipes.entries().stream().filter(r->r.key().equals("ANIMATION_TABLET")).findFirst().orElseThrow();check(recipe.ingredients().get(4).test(new ItemStack(FocusResearch.item("golem_core_blank")))&&recipe.cost().getAmount(thaumcraft.api.aspects.Aspect.AIR)==25&&dev.eugheist.tc4modern.ResearchWarp.amount("ANIMATION_TABLET")==1,"original blank core recipe and warp");
        for(int slot:new int[]{1,3,5})check(recipe.ingredients().get(slot).test(new ItemStack(Items.IRON_INGOT))&&!recipe.ingredients().get(slot).test(new ItemStack(Items.DIAMOND)),"original tablet iron ingredient slot "+slot);
        System.out.println("TT TABLET AUDIT: ALL PASS (windup, real mining/drops/durability, cancellation, sword attack, hoe use, redstone mode, trigger, persistence, extra items, menu validation, recipe/warp)");
    }finally{for(var entity:level.getEntities((net.minecraft.world.entity.Entity)null,new AABB(pos).inflate(3)))entity.discard();for(var block:java.util.List.of(pos,at,at.below())){level.removeBlockEntity(block);level.removeBlock(block,false);}}}
}
